BEGIN;
CREATE TABLE enterprise_workflow.publication_evidence(enterprise_id uuid NOT NULL,id uuid NOT NULL,publication_id uuid NOT NULL,receipt_revision integer NOT NULL,uploader text NOT NULL,name text NOT NULL,note text NOT NULL,bytes bigint NOT NULL CHECK(bytes>0 AND bytes<=16777216),sha256 text NOT NULL CHECK(sha256 ~ '^[a-f0-9]{64}$'),fingerprint text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(enterprise_id,id),FOREIGN KEY(enterprise_id,publication_id,receipt_revision) REFERENCES enterprise_workflow.publication_revisions(enterprise_id,publication_id,revision));
CREATE INDEX publication_evidence_parent ON enterprise_workflow.publication_evidence(enterprise_id,publication_id,created_at DESC,id);
CREATE TABLE enterprise_workflow.publication_evidence_scans(ordinal bigserial PRIMARY KEY,id uuid NOT NULL UNIQUE,enterprise_id uuid NOT NULL,asset_id uuid NOT NULL,sha256 text NOT NULL,bytes bigint NOT NULL,subject text NOT NULL,status text NOT NULL CHECK(status IN ('unscanned','clean','infected','error')),policy_key text NOT NULL,policy_label text NOT NULL,engine text,signature text,reason text,created_at timestamptz NOT NULL,valid_until timestamptz,FOREIGN KEY(enterprise_id,asset_id) REFERENCES enterprise_workflow.publication_evidence(enterprise_id,id));
CREATE INDEX publication_scan_latest ON enterprise_workflow.publication_evidence_scans(enterprise_id,asset_id,ordinal DESC);
CREATE TABLE enterprise_workflow.publication_file_audit(id uuid PRIMARY KEY,enterprise_id uuid NOT NULL,publication_id uuid NOT NULL,asset_id uuid,subject text NOT NULL,operation text NOT NULL,detail jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(enterprise_id,publication_id) REFERENCES enterprise_workflow.publications(enterprise_id,id));
INSERT INTO enterprise_workflow.schema_version VALUES(31);
COMMIT;
